import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"链地址与开放寻址","description":"","frontmatter":{"title":"链地址与开放寻址","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chaining-open-address.md","filePath":"cs/chaining-open-address.md","lastUpdated":1789023840000}'),c={name:"cs/chaining-open-address.md"};function E(_,a,m,A,u,f){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="链地址与开放寻址" tabindex="-1">链地址与开放寻址 <a class="header-anchor" href="#链地址与开放寻址" aria-label="Permalink to &quot;链地址与开放寻址&quot;">​</a></h1><div class="epigraph"><p>同一槽的碰撞要么挂成链表，要么沿探测序列找下一个空位；删除和负载因子对两种策略不对称。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Knuth, TAOCP 卷 3 整理</footer></div><p><a href="/cs/hash-function">上一课</a>给出 \\(h(k)\\) 和负载 \\(\\alpha\\)，碰撞未处理。<a href="/cs/hash-function">链表与局部性代价</a>已能挂节点。<a href="/cs/array-random-access">数组与随机访问</a>已能在表内改槽。本课不重讲全域族。缺口是两种表示：链地址与开放寻址，以及它们对 \\(\\alpha\\)、删除、局部性的不同合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(h(k)\\) 只指出候选槽。多键同槽若直接覆盖就丢数据。缺口是放置策略。链：槽存指针，碰撞的键在链表（或树）上。开放：表内全是键或空，冲突则 \\(h(k), h(k)+1, \\ldots\\) 或双重散列探测。</p><p>期望查找：链在简单均匀下 \\(\\Theta(1+\\alpha)\\)。开放要求 \\(\\alpha\\lt 1\\)，成功查找依赖探测序列，一次聚集会让 \\(\\alpha\\) 不大时已变慢。本课钉线性探测的聚集风险，推荐双重散列或平方探测作为对照，不把实现调参写完。</p><p><span class="marginnote">删除：链可摘节点。开放必须用墓碑，否则探测链断裂。墓碑抬高有效 \\(\\alpha\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链地址：插入在槽头加节点 \\(\\Theta(1)\\)。查找扫该槽的链。\\(\\alpha\\) 可大于 1。再散列在 \\(\\alpha\\) 过大时触发，摊还与动态表相同。</p><p>开放寻址：插入沿探测找空槽。查找沿同一序列直到空（或墓碑策略下的终止条件）。表满无法插。</p>',10)),(e(),s(d,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22h(k)%22%5D%20--%3E%20CH%5B%22%E9%93%BE%EF%BC%9A%E6%A7%BD%E4%B8%8A%E9%93%BE%E8%A1%A8%22%5D%0A%20%20H%20--%3E%20OA%5B%22%E5%BC%80%E6%94%BE%EF%BC%9A%E8%A1%A8%E5%86%85%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20CH%20--%3E%20A1%5B%22%CE%B1%20%E5%8F%AF%20%3E1%22%5D%0A%20%20OA%20--%3E%20A2%5B%22%CE%B1%20%EF%BC%9C1%EF%BC%8C%E6%80%95%E8%81%9A%E9%9B%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>链的指针追逐破坏空间局部性；开放的线性探测吃同一 cache 行，命中时更快，缺失时一次缺行可能覆盖多个槽。这是<a href="/cs/locality-principle">局部性原理</a>对两种表示的注脚，渐近期望仍由 \\(\\alpha\\) 主导。</p><p>最坏仍 \\(\\Theta(n)\\)。需要最坏对数则退回树，或链上挂红黑（Java 曾对长链这样做）——那是混合，合同变成「期望常数，最坏对数」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Cuckoo、Hopscotch。也不把布隆过滤器当成字典：它有假阳性、无删除或删除另议。并发散列是另一课。</p><p>后课默认：无序字典可用链或开放寻址，期望 \\(O(1+\\alpha)\\)。有序、可范围查询仍用树。跳表用随机高度提供另一套期望对数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链：\\(\\alpha\\) 可超过 1，删除简单，指针局部性差。</li><li>开放：表内探测，\\(\\alpha\\lt 1\\)，删除用墓碑，线性探测会聚集。</li><li>随机多层链表是下一课跳表。</li><li>出处：Cormen et al. 第 11 章；Knuth, <em>TAOCP</em> 卷 3。</li></ul>',8))])}const T=l(c,[["render",E]]);export{C as __pageData,T as default};
